Task ID: nrf_l1_033
Category: network_routing_forwarding
Difficulty: level_1

Original Instruction:
Write an XDP program that reflects incoming Ethernet frames back out the ingress interface (XDP_TX) by swapping the source and destination MAC addresses. Pass non-matching or malformed packets.

Technical Requirements:
- Swap Ethernet destination MAC and source MAC addresses
- Return XDP_TX for valid Ethernet frames
- Pass truncated frames with XDP_PASS
- Validate packet boundaries

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

SEC("xdp")
int xdp_route_nrf_l1_033(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    // FAULT: Reading IP header without checking (ip + 1) bounds against data_end
    struct iphdr *ip = (void *)(eth + 1);
    if (ip->protocol != IPPROTO_ICMP)
        return XDP_PASS;

    unsigned char tmp[ETH_ALEN];
    __builtin_memcpy(tmp, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp, ETH_ALEN);

    return XDP_TX;
}

char _license[] SEC("license") = "GPL";
```

